content:
@layer components {
  .drawer {
    position: fixed;
    inset-block: 0;
    inline-size: min(24rem, 90vw);
    background-color: var(--shelf-bgColor-raised);
    box-shadow: var(--shelf-shadow-lg);
    z-index: 10;
  }
}

@layer components {
  .drawer {
    position: fixed;
    inset-block: 0;
    inline-size: min(24rem, 90vw);
    background-color: var(--shelf-bgColor-raised);
    box-shadow: var(--shelf-shadow-lg);
    z-index: var(--shelf-z-drawer);
  }
}

@layer tokens {
  :root {
    --shelf-z-base: 0;
    --shelf-z-sticky: 100;
    --shelf-z-dropdown: 200;
    --shelf-z-drawer: 300;
    --shelf-z-dialog: 400;
    --shelf-z-toast: 500;
  }
}

@layer base {
  *, *::before, *::after { box-sizing: border-box; }
  body {
    margin: 0;
    background-color: var(--shelf-bgColor-default);
    color: var(--shelf-fgColor-default);
    font-family: var(--shelf-font-family-base);
  }
}

@layer components {
  .book-card {
    position: relative;
    z-index: 0;
    border-radius: var(--shelf-radius-md);
    background-color: var(--shelf-bgColor-raised);
    box-shadow: var(--shelf-shadow-md);
  }
}

@layer components {
  .chip-bar {
    position: sticky;
    inset-block-start: 0;
    z-index: var(--shelf-z-sticky);
    display: flex;
    gap: var(--shelf-space-sm);
    padding: var(--shelf-space-sm) var(--shelf-space-md);
    background-color: var(--shelf-bgColor-default);
  }
}

@layer components {
  .app-overlay {
    position: fixed;
    inset: 0;
    z-index: 999;
    background-color: var(--shelf-bgColor-overlay);
  }
}
